package Loops;

public class loops {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        for(int i =1; i < 9;i++) {
        	System.out.println("Hello Loops" + i);
        }
        
        
        int n=1;
        while(n <= 10) {
        	System.out.println(n);
        	n++;
        }
        
        int z = 1;
        while(z > 6) {
        	System.out.println(z);
        	z--;
        }
        
        
	}

}
